Ensure that `procedureStepEvidence` is robust against cases where `stepContext` or `stepContext.item` is undefined/null to prevent potential `TypeError`s during dereferencing.

```suggestion
function procedureStepEvidence(stepContext, paths, supportsFields) {
  if (!stepContext?.item) return null;
  return evidenceRef({
    evidenceRefId: refId('evidence:procedure_step', stepContext.item.procedure_step_candidate_id),
    sourceFamily: 'procedure_step_map',
    artifactPath: paths.procedureStepMapIn,
    pointer: `/anchor_to_procedure_step_mappings/${stepContext.index}`,
    supportsFields,
  });
}
```

