Ensure that `buildAssertionsForRow` is robust against cases where `firstStep` is undefined/null or does not contain `item` to prevent potential `TypeError`s during dereferencing.

```javascript
function buildAssertionsForRow(context, producedShard) {
  const modelId = context.model?.item?.procedure_model_candidate_id;
  const modelLabel = context.model?.item?.effective_method_label ?? context.skill.canonical_name;
  const firstStep = context.steps[0];
  const questionText = questionTextEvidence(context, ['subject', 'predicate', 'object', 'scope']);
  const procedureModel = procedureModelEvidence(context, ['predicate', 'object']);
  const visual = visualReceiptEvidence(context, ['scope', 'source_visual_context']);
  const questionProcedureEvidence = [questionText, procedureModel, visual].filter(Boolean);

  const assertions = [
    assertionBase(context, producedShard, 1, 'question_uses_procedure', {
      ref_type: 'ProcedureModel',
      ref_id: modelId,
      label: modelLabel,
    }, {
      evidenceRefs: questionProcedureEvidence,
      confidenceScore: 0.8,
      confidenceExplanation:
        'Checked-in question text and ProcedureModel mapping identify the bounded procedure used by this scheduled row.',
    }),
    assertionBase(context, producedShard, 2, 'question_invokes_concept', {
      ref_type: 'Concept',
      ref_id: context.concept.ref_id,
      canonical_name: context.concept.canonical_name,
    }, {
      evidenceRefs: [questionText, procedureModel],
      confidenceScore: 0.76,
      confidenceExplanation:
        'Topic path, checked-in question text, and procedure label support this bounded concept invocation.',
    }),
    assertionBase(context, producedShard, 3, 'question_requires_skill', {
      ref_type: 'Skill',
      ref_id: context.skill.ref_id,
      canonical_name: context.skill.canonical_name,
    }, {
      evidenceRefs: [questionText, procedureModel],
      confidenceScore: 0.75,
      confidenceExplanation:
        'The checked-in task wording and procedure label require this bounded skill.',
    }),
  ];

  if (firstStep?.item) {
    assertions.push(
      assertionBase(context, producedShard, 4, 'procedure_has_step', {
        ref_type: 'ProcedureStep',
        ref_id: firstStep.item.procedure_step_candidate_id,
        step_key: firstStep.item.step_key,
      }, {
        subject: {
          ref_type: 'ProcedureModel',
          ref_id: modelId,
        },
        scope: {
          scope_kind: 'procedure_step',
          subject_code: SUBJECT_CODE,
          question_id: context.schedulerRow.question_row_id,
          procedure_model_id: modelId,
          procedure_step_id: firstStep.item.procedure_step_candidate_id,
        },
        evidenceRefs: [
          procedureModel,
          procedureStepEvidence(firstStep, context.paths, ['subject', 'predicate', 'object']),
        ].filter(Boolean),
        confidenceScore: 0.74,
        confidenceExplanation:
          'Checked-in ProcedureStep mapping links this procedure model to the referenced step.',
      })
    );
  }

  return assertions;
}
