      input_diagnostics: inputDiagnostics,
    }));
  checks.push(validatorStatus(inputs.schedulerValidator) === 'pass'
    ? passCheck('issue_1370_scheduler_validator_passed', {
      scheduler_validator_status: validatorStatus(inputs.schedulerValidator),
    })
    : failCheck('issue_1370_scheduler_validator_passed', 'scheduler_validator_not_passed', {
      scheduler_validator_status: validatorStatus(inputs.schedulerValidator),
    }));
  checks.push(
    (summary.provisional_safe_status_proposal_growth_against_1369 ?? 0) > 0 &&
      (summary.produced_candidate_row_count ?? 0) > 0 &&
      (summary.produced_candidate_row_count ?? 0) < schedulerRemaining
      ? passCheck('useful_growth_is_primary_metric_not_full_row_touch', {
        provisional_safe_growth:
          summary.provisional_safe_status_proposal_growth_against_1369,
