      })
      : failCheck(
        'useful_growth_is_primary_metric_not_full_row_touch',
        'no_useful_growth_or_full_row_touch_claim',
        {
          provisional_safe_growth:
            summary.provisional_safe_status_proposal_growth_against_1369,
          produced_candidate_row_count: summary.produced_candidate_row_count,
          scheduler_remaining_row_count_context_only: schedulerRemaining,
        },
      ),
  );
  checks.push(preflightFailures.length === 0
    ? passCheck('produced_shards_pass_existing_codex_preflight', {
      produced_shard_count: (candidateLayer?.produced_shards ?? []).length,
    })
    : failCheck('produced_shards_pass_existing_codex_preflight', 'shard_preflight_failed', {
      failed_shards: preflightFailures,
    }));
  checks.push(
    candidateLayer?.boundary?.proposal_layer_only === true &&
      candidateLayer?.boundary?.canonical_accepted_or_provisional_layers_not_mutated === true &&
      summary.accepted_status_proposal_count === 0 &&
      (candidateLayer?.semantic_assertion_proposals ?? []).every((assertion) => (
        assertion.status_proposal === 'provisional_safe' &&
