Ensure that `renderShardRows` is robust against cases where `candidateLayer` or `candidateLayer.produced_shards` is undefined/null to prevent potential `TypeError`s during dereferencing.

```suggestion
function renderShardRows(candidateLayer) {
  return (candidateLayer?.produced_shards ?? []).slice(0, 12).map((shard) => (
    `| ${shard.source_scheduler_shard_id} | ${shard.shard_id} | ${shard.row_count} | ${shard.assertion_count} | ${shard.preflight_status} |`
  )).join('\n');
}
```

